**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        cout << n << " = ";
        int tmp = n;
        int liczbaCzynnikow = 0;
        bool first = true;
        for (int d = 2; d * d <= tmp; d++) {
            if (tmp % d == 0) {
                int cnt = 0;
                while (tmp % d == 0) {
                    cnt++;
                    tmp /= d;
                }
                liczbaCzynnikow++;
                if (!first) cout << " * ";
                first = false;
                if (cnt > 1) cout << d << "^" << cnt;
                else cout << d;
            }
        }
        if (tmp > 1) {
            if (!first) cout << " * ";
            cout << tmp;
            liczbaCzynnikow++;
        }
        cout << " (" << liczbaCzynnikow;
        if (liczbaCzynnikow == 1) cout << " czynnik pierwszy)" << endl;
        else cout << " czynniki pierwsze)" << endl;
        if (liczbaCzynnikow == 2) ile++;
    }
    cout << "Liczby z dokladnie 2 roznymi czynnikami pierwszymi: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm faktoryzacji: iteruj od d=2, wyciagaj czynnik az n niepodzielne, przejdz do d+1. Warunek `d*d <= tmp` gwarantuje, ze po petli `tmp > 1` jest czynnikiem pierwszym.

